  claimReadyTask(workerId:string,capabilities:string[],tokenHash:string,expiresAt:string,timestamp:string){return this.db.transaction(()=>{const rows=this.db.prepare(`SELECT t.* FROM mission_tasks t JOIN missions m ON m.id=t.mission_id LEFT JOIN task_leases l ON l.task_id=t.id WHERE t.status='pending' AND m.status IN ('pending','running') AND l.task_id IS NULL ORDER BY m.created_at,t.created_at LIMIT 200`).all() as Row[];for(const row of rows){const candidate=this.missionTask(row);if(!capabilities.includes('*')&&!capabilities.includes(candidate.kind)&&!(candidate.kind.startsWith('tool:')&&capabilities.includes('tool')))continue;const statuses=this.db.prepare('SELECT task_key,status FROM mission_tasks WHERE mission_id=?').all(candidate.missionId) as {task_key:string;status:string}[];const completed=new Set(statuses.filter(item=>item.status==='completed').map(item=>item.task_key));if(!candidate.dependsOn.every(dep=>completed.has(dep)))continue;const lease:TaskLease={taskId:candidate.id,missionId:candidate.missionId,workerId,tokenHash,expiresAt,heartbeatAt:timestamp,createdAt:timestamp};this.db.prepare('INSERT INTO task_leases VALUES(?,?,?,?,?,?,?)').run(lease.taskId,lease.missionId,workerId,tokenHash,expiresAt,timestamp,timestamp);this.db.prepare(`UPDATE mission_tasks SET status='running',attempts=attempts+1,progress=MAX(progress,1),updated_at=? WHERE id=?`).run(timestamp,candidate.id);this.db.prepare(`UPDATE missions SET status='running',updated_at=? WHERE id=?`).run(timestamp,candidate.missionId);const task=this.getMissionTask(candidate.id)!;const missionRow=this.db.prepare('SELECT * FROM missions WHERE id=?').get(candidate.missionId) as Row;return{mission:this.mission(missionRow),task,lease}}return undefined})()}
  getTaskLease(taskId:string){const row=this.db.prepare('SELECT * FROM task_leases WHERE task_id=?').get(taskId) as Row|undefined;return row?this.taskLease(row):undefined}
  heartbeatTaskLease(taskId:string,workerId:string,tokenHash:string,expiresAt:string,timestamp:string){const lease=this.getTaskLease(taskId);if(!lease||lease.workerId!==workerId||lease.tokenHash!==tokenHash)throw new NotFoundError('Lease de tarefa');this.db.prepare('UPDATE task_leases SET expires_at=?,heartbeat_at=? WHERE task_id=?').run(expiresAt,timestamp,taskId);return{...lease,expiresAt,heartbeatAt:timestamp}}
  releaseTaskLease(taskId:string,workerId:string){this.db.prepare('DELETE FROM task_leases WHERE task_id=? AND worker_id=?').run(taskId,workerId)}
  recoverExpiredTaskLeases(timestamp:string){let recovered=0,failed=0;this.db.transaction(()=>{const rows=this.db.prepare('SELECT l.task_id,t.attempts,t.max_attempts,t.mission_id FROM task_leases l JOIN mission_tasks t ON t.id=l.task_id WHERE l.expires_at<=?').all(timestamp) as {task_id:string;attempts:number;max_attempts:number;mission_id:string}[];for(const row of rows){if(row.attempts<row.max_attempts){this.db.prepare(`UPDATE mission_tasks SET status='pending',error='Worker lease expired',updated_at=? WHERE id=?`).run(timestamp,row.task_id);recovered++}else{this.db.prepare(`UPDATE mission_tasks SET status='failed',error='Worker lease expired after maximum attempts',updated_at=? WHERE id=?`).run(timestamp,row.task_id);this.db.prepare(`UPDATE missions SET status='failed',updated_at=? WHERE id=?`).run(timestamp,row.mission_id);failed++}this.db.prepare('DELETE FROM task_leases WHERE task_id=?').run(row.task_id)}})();return{recovered,failed}}
