  createDivineOsModule(module:DivineOsModule){this.db.prepare('INSERT INTO divine_os_modules VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(module.id,module.userId,module.divineOsProjectId,module.name,module.version,JSON.stringify(module.capabilities),JSON.stringify(module.dependencies),JSON.stringify(module.permissions),module.status,JSON.stringify(module.manifest),module.createdAt,module.updatedAt);return module}
  listDivineOsModules(projectId:string,userId:string){return(this.db.prepare('SELECT * FROM divine_os_modules WHERE divine_os_project_id=? AND user_id=? ORDER BY rowid').all(projectId,userId) as Row[]).map(row=>this.divineOsModule(row))}

  createUser(user: StoredUser) { try { this.db.prepare('INSERT INTO users VALUES (?, ?, ?, ?, ?)').run(user.id, user.email, user.name, user.passwordHash, user.createdAt); return user } catch { throw new AppError('Este e-mail já está cadastrado.', 409, 'EMAIL_EXISTS') } }
  findUserByEmail(email: string) { const row = this.db.prepare('SELECT * FROM users WHERE email=?').get(email) as Row | undefined; return row ? this.user(row) : undefined }
  findUserById(userId: string) { const row = this.db.prepare('SELECT * FROM users WHERE id=?').get(userId) as Row | undefined; return row ? this.user(row) : undefined }
  saveRefreshToken(token: StoredRefreshToken) { this.db.prepare('INSERT INTO refresh_tokens VALUES (?, ?, ?, ?, ?, ?)').run(token.id, token.userId, token.tokenHash, token.expiresAt, token.revokedAt ?? null, token.createdAt) }
  findRefreshToken(tokenHash: string) { const row = this.db.prepare('SELECT * FROM refresh_tokens WHERE token_hash=?').get(tokenHash) as Row | undefined; return row ? this.refresh(row) : undefined }
  revokeRefreshToken(tokenHash: string) { this.db.prepare('UPDATE refresh_tokens SET revoked_at=? WHERE token_hash=?').run(now(), tokenHash) }
  revokeUserRefreshTokens(userId: string) { this.db.prepare('UPDATE refresh_tokens SET revoked_at=? WHERE user_id=? AND revoked_at IS NULL').run(now(), userId) }
  updateUserPassword(userId:string,passwordHash:string){this.db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(passwordHash,userId)}
  savePasswordResetToken(token:StoredPasswordResetToken){this.db.prepare('INSERT INTO password_reset_tokens VALUES(?,?,?,?,?,?)').run(token.id,token.userId,token.tokenHash,token.expiresAt,token.usedAt??null,token.createdAt)}
  findPasswordResetToken(tokenHash:string){const row=this.db.prepare('SELECT * FROM password_reset_tokens WHERE token_hash=?').get(tokenHash) as Row|undefined;return row?this.passwordReset(row):undefined}
  consumePasswordResetToken(tokenHash:string,usedAt:string){this.db.prepare('UPDATE password_reset_tokens SET used_at=? WHERE token_hash=?').run(usedAt,tokenHash)}
  audit(event: AuditEvent) { this.db.prepare('INSERT INTO audit_events VALUES (?, ?, ?, ?, ?, ?)').run(event.id, event.userId ?? null, event.action, event.resource ?? null, event.metadata ? JSON.stringify(event.metadata) : null, event.createdAt) }
  listAudit(userId: string, limit = 100) { return (this.db.prepare('SELECT * FROM audit_events WHERE user_id=? ORDER BY created_at DESC LIMIT ?').all(userId, limit) as Row[]).map(row => ({ id: String(row.id), userId: row.user_id ? String(row.user_id) : undefined, action: String(row.action), resource: row.resource ? String(row.resource) : undefined, metadata: json<Record<string, unknown>>(row.metadata as string | null), createdAt: String(row.created_at) })) }
  close() { this.db.close() }

